create database delivery;
use delivery;
select * from order_transactions;
select OrderID,OrderDate from order_transactions where Year(OrderDate)=2024;
select distinct OrderStatus from order_transactions;
select distinct PaymentMethodID from order_transactions;
select sum(TotalPrice)as total_sales,sum(Quantity) as total_qty from order_transactions;
select DeliveryPartnerID,count(OrderID) as total_orders from order_transactions group by DeliveryPartnerID order by Total_orders DESC;
select CustomerID,sum(TotalPrice) as total_purchase from order_transactions group by CustomerID order by total_purchase desc limit 10;
select OrderID,OrderStatus from order_transactions where OrderStatus='Cancelled';
select distinct OrderStatus from order_transactions;
select avg(DiscountApplied) as Avg_discount from order_transactions;
select PaymentMethodID,count(*) as count from order_transactions group by PaymentMethodID order by count desc limit 1;
select StoreID,sum(TotalPrice) as Total_Sales,sum(Quantity) as total_quantity from order_transactions group by StoreID order by Total_Sales desc;
select month(OrderDate) as month,sum(TotalPrice) as Total_sales from order_transactions group by month(OrderDate) order by month;
select DeliveryPartnerID,avg(DeliveryTimeMinutes) as Avg_delivery_time from order_transactions group by DeliveryPartnerID order by Avg_delivery_time;
select StoreID,count(*) as Cancelled_orders from order_transactions where OrderStatus='Cancelled' group by StoreID order by Cancelled_orders desc;
select DeliveryPartnerID,count(*) as delivered_orders from order_transactions where OrderStatus='Delivered' group by DeliveryPartnerID order by  delivered_orders desc limit 5;
select PaymentMethodID,sum(TotalPrice) as total_revenue from order_transactions group by PaymentMethodID order by total_revenue desc limit 1;
select ProductID,count(*) as order_count from order_transactions group by ProductID having count(*)>10 order by order_count desc;
select StoreID,avg(TotalPrice) as avg_order_value from order_transactions group by StoreID order by avg_order_value desc;
commit;
with cust_sales as(select StoreID,CustomerID,sum(TotalPrice)as Total_sales from order_transactions group by StoreID,CustomerID) select StoreID,CustomerID,Total_sales,rank() over(partition by StoreID order by Total_sales desc)as cust_rank from cust_sales;
select OrderDate,sum(TotalPrice) as running_sales,sum(sum(TotalPrice)) over(order by OrderDate)as cumulative_sales from order_transactions group by OrderDate order by OrderDate;
with yearly_sales as(select year(OrderDate) as year,sum(TotalPrice) as total_sales from order_transactions group by year(OrderDate))select year,total_sales,lag(total_sales) over( order by year) as prev_year_sales,round((total_sales-lag(total_sales)over (order by year))/ lag(total_sales)over(order by year)*100,2) as Percentage from yearly_sales;
with prod_sales as(select StoreID,ProductID,sum(TotalPrice) as total_sales from order_transactions group by StoreID,ProductID),rank_prod as(select StoreID,ProductID,total_sales,row_number()over (partition by StoreID order by total_sales desc)as prod_rank from prod_sales)select * from rank_prod where prod_rank<=3;
select CustomerID,sum(TotalPrice) as total_spend from order_transactions group by CustomerID having sum(TotalPrice)>(select avg(cust_total) from (select CustomerID,sum(TotalPrice) as cust_total from order_transactions group by CustomerID) as cust_data)order by total_spend desc;
with monthly_sales as(select month(OrderDate) as month,sum(TotalPrice) as total_sales from order_transactions group by month(OrderDate))select month,total_sales,lag(total_sales) over (order by month) as previous_month_sales,total_sales-lag(total_sales) over(order by month) as change_sales from monthly_sales order by month;
with cust_sales as(select CustomerID,sum(TotalPrice) as total_sales from order_transactions group by CustomerID)select CustomerID,total_sales,case when total_sales >=30000 then 'High' when total_sales >=20000 then 'Medium' else 'Low' end as cust_value from cust_sales order by total_sales desc;
select case when DiscountApplied <10 then '0-10%' when DiscountApplied <20 then '10-20%' else '20%+' end as Disc_level,avg(TotalPrice) as avg_sales from order_transactions group by  Disc_level order by avg_sales;
select StoreID,avg(DiscountApplied)as avg_discount,avg(TotalPrice) as avg_sales from order_transactions group by StoreID order by avg_discount desc;
select DeliveryPartnerID,count(*) as total_orders,avg(DeliveryTimeMinutes) as avg_delivery_time from order_transactions group by DeliveryPartnerID order by total_orders desc;
select DeliveryPartnerID,count(*) as total_orders,avg(DeliveryTimeMinutes) as avg_delivery_time from order_transactions group by DeliveryPartnerID order by total_orders desc limit 1;
